{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table snitch_db.maplemonk.channel_targets_tracking as WITH Base_Data AS ( SELECT lower(L_1_CATEGORY) AS L1_category, lower(category) category, CHANNELS, TRY_TO_NUMBER(REPLACE(qty, \',\', \'\')) AS target_qty, TRY_TO_NUMBER(REPLACE(revenue, \',\', \'\')) AS target_revenue, TRY_TO_DOUBLE(REPLACE(gm_, \'%\', \'\')) AS GM_target, month, COALESCE( TRY_TO_DATE(TRIM(month), \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(month) || \'-01\', \'YYYY-MM-DD\'), TRY_TO_DATE(TRIM(month), \'MON-YY\'), TRY_TO_DATE(TRIM(month), \'MONTH-YY\'), TRY_TO_DATE(TRIM(month) || \'-2026\', \'MONTH-YYYY\'), TRY_TO_DATE(TRIM(month) || \'-2026\', \'MON-YYYY\') ) AS month_date FROM snitch_db.maplemonk.channel_targets_sheet1 ), meta_map AS ( SELECT UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) AS sku_group_clean, COALESCE( MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LONG TAIL\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'PLUS\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'LUXE\' THEN l1_category END), MIN(CASE WHEN UPPER(TRIM(l1_category)) = \'SNITCH\' THEN l1_category END), MIN(l1_category) ) AS l1_category, COALESCE( MIN(CASE WHEN UPPER(TRIM(category)) = \'SHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TSHIRTS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'JEANS\' THEN category END), MIN(CASE WHEN UPPER(TRIM(category)) = \'TROUSERS\' THEN category END), MIN(category) ) AS category, MAX(cogs) AS sku_cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku GROUP BY 1 ), sales_actual_base AS ( SELECT DATE_TRUNC(\'MONTH\', h.date) AS month_date, lower(m.l1_category) l1_category, lower(m.category) category, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'MP\' WHEN type = \'Store\' THEN \'Offline\' END AS channels, SUM(h.gross_quantity) AS sales_qty, SUM(h.gross_sales) AS sales_revenue, SUM(h.gross_quantity * COALESCE(m.sku_cogs, 0)) AS cogs FROM snitch_db.maplemonk.horizontal_sales_categories h LEFT JOIN meta_map m ON UPPER( IFF( UPPER(REPLACE(h.SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(h.SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(h.SKU_GROUP, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(h.SKU_GROUP, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(h.SKU_GROUP, \' \', \'\'), \'-\', 1) ) ) = m.sku_group_clean WHERE h.date >= \'2026-04-01\' GROUP BY 1, 2, 3, 4 ), mp_sor_raw AS ( SELECT UPPER(TRIM(a.style)) AS sku_group, TRY_TO_DATE(NULLIF(TRIM(a.order_created_date), \'\'), \'YYYYMMDD\') AS date, TRY_TO_NUMBER(REPLACE(a.sales, \',\', \'\')) AS qty, TRY_TO_NUMBER(REPLACE(a.revenue, \',\', \'\')) AS revenue FROM snitch_db.maplemonk.S3_MYNTRA_B2B_GP a UNION ALL SELECT UPPER(TRIM(a.STYLE)) AS sku_group, TRY_TO_DATE(NULLIF(TRIM(a.order_date_key), \'\'), \'YYYYMMDD\') AS date, TRY_TO_NUMBER(REPLACE(a.units, \',\', \'\')) AS qty, TRY_TO_NUMBER(REPLACE(a.SP_Qty, \',\', \'\')) AS revenue FROM snitch_db.maplemonk.S3_Flipkart_B2B_GP a ), mp_sor AS ( SELECT DATE_TRUNC(\'MONTH\', s.date) AS month_date, lower(m.l1_category) AS l1_category, lower(m.category) AS category, \'MP\' AS channels, SUM(s.qty) AS sales_qty, SUM(s.revenue) AS sales_revenue, SUM(s.qty * COALESCE(m.sku_cogs, 0)) AS cogs FROM mp_sor_raw s LEFT JOIN meta_map m ON UPPER( IFF( UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(s.sku_group, \' \', \'\')) LIKE \'4C-%\', SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1) || \'-\' || SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 2), SPLIT_PART(REPLACE(s.sku_group, \' \', \'\'), \'-\', 1) ) ) = m.sku_group_clean WHERE s.date >= \'2026-04-01\' GROUP BY 1, 2, 3 ), sales_actual AS ( SELECT month_date, l1_category, category, channels, SUM(sales_qty) AS sales_qty, SUM(sales_revenue) AS sales_revenue, SUM(cogs) AS cogs FROM ( SELECT * FROM sales_actual_base UNION ALL SELECT * FROM mp_sor ) GROUP BY 1, 2, 3, 4 ), final_regular AS ( SELECT b.month_date, b.month, b.L1_category, b.category, b.channels, b.target_qty, COALESCE(s.sales_qty, 0) AS sales_qty, b.target_qty - COALESCE(s.sales_qty, 0) AS remaining_target_qty, COALESCE(ROUND(((b.target_qty - COALESCE(s.sales_qty, 0)) / NULLIF(b.target_qty, 0)) * 100), 0) AS pct_remaining_qty, b.target_revenue, COALESCE(s.sales_revenue, 0) AS sales_revenue, b.target_revenue - COALESCE(s.sales_revenue, 0) AS remaining_target_revenue, COALESCE(ROUND(((b.target_revenue - COALESCE(s.sales_revenue, 0)) / NULLIF(b.target_revenue, 0)) * 100), 0) AS pct_remaining_revenue, b.GM_target, COALESCE(s.cogs, 0) AS cogs, ROUND((1 - (COALESCE(s.cogs, 0) / NULLIF(COALESCE(s.sales_revenue, 0), 0))) * 100, 2) AS gross_margin, CASE WHEN b.month_date = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN ROUND(b.target_qty * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) ELSE b.target_qty END AS target_qty_till_date, CASE WHEN b.month_date = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN ROUND(b.target_revenue * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) ELSE b.target_qty END AS target_revenue_till_date, ROUND(b.GM_target * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) AS target_gm_till_date FROM Base_Data b LEFT JOIN sales_actual s ON b.month_date = s.month_date AND UPPER(TRIM(b.L1_category)) = UPPER(TRIM(s.L1_category)) AND UPPER(TRIM(b.category)) = UPPER(TRIM(s.category)) AND UPPER(TRIM(b.channels)) = UPPER(TRIM(s.channels)) WHERE lower(b.category) NOT IN (\'hoodies\', \'jackets\', \'sweaters\') ), winterwear_final AS ( SELECT COALESCE(b.month_date, s.month_date) AS month_date, b.month, NULL AS L1_category, COALESCE(b.category, s.category) AS category, COALESCE(b.channels, s.channels) AS channels, b.target_qty, COALESCE(s.sales_qty, 0) AS sales_qty, COALESCE(b.target_qty, 0) - COALESCE(s.sales_qty, 0) AS remaining_target_qty, COALESCE(ROUND(((COALESCE(b.target_qty,0) - COALESCE(s.sales_qty, 0)) / NULLIF(b.target_qty, 0)) * 100), 0) AS pct_remaining_qty, b.target_revenue, COALESCE(s.sales_revenue, 0) AS sales_revenue, COALESCE(b.target_revenue, 0) - COALESCE(s.sales_revenue, 0) AS remaining_target_revenue, COALESCE(ROUND(((COALESCE(b.target_revenue,0) - COALESCE(s.sales_revenue, 0)) / NULLIF(b.target_revenue, 0)) * 100), 0) AS pct_remaining_revenue, b.GM_target, COALESCE(s.cogs, 0) AS cogs, ROUND((1 - (COALESCE(s.cogs, 0) / NULLIF(COALESCE(s.sales_revenue, 0), 0))) * 100, 2) AS gross_margin, CASE WHEN COALESCE(b.month_date, s.month_date) = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN ROUND(COALESCE(b.target_qty,0) * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) ELSE b.target_qty END AS target_qty_till_date, CASE WHEN COALESCE(b.month_date, s.month_date) = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN ROUND(COALESCE(b.target_revenue,0) * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) ELSE b.target_qty END AS target_revenue_till_date, ROUND(b.GM_target * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())), 2) AS target_gm_till_date FROM (SELECT * FROM Base_Data WHERE lower(category) IN (\'hoodies\', \'jackets\', \'sweaters\')) b FULL OUTER JOIN (SELECT * FROM sales_actual WHERE category IN (\'hoodies\', \'jackets\', \'sweaters\')) s ON b.month_date = s.month_date AND UPPER(TRIM(b.category)) = UPPER(TRIM(s.category)) AND UPPER(TRIM(b.channels)) = UPPER(TRIM(s.channels)) ) SELECT * FROM final_regular UNION ALL SELECT * FROM winterwear_final ORDER BY month_date, L1_category, category, channels;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            